 Map<String,Object> historyEntry(Map<String,Object> fact,String table,String label,String summary,Object actor,String actorLabel){var e=new LinkedHashMap<String,Object>();e.put("id",fact.get(table+"_id").toString());e.put("label",label);e.put("summary",summary);e.put("occurredAt",time(fact.get("created_at")).toString());e.put("actorAppointmentId",actor.toString());e.put("actorLabel",actorLabel);return e;}
