  var binding=row(c,"select * from contract.revision_review_binding where tenant_id=? and revision_review_binding_id=?",tenant,ready.get("review_binding_id"));
  var approvals=rows(c,"select d.revision_approval_decision_id from contract.revision_approval_requirement q join contract.revision_approval_decision d on d.tenant_id=q.tenant_id and d.requirement_id=q.revision_approval_requirement_id where q.tenant_id=? and q.contract_revision_id=? order by q.requirement_code",tenant,version.get("contract_revision_id"));
